/// `base.powf(exponent)`, from the table when `exponent` is a slider step
/// k / 11 of a tabled base on the browser build.
pub fn step_pow(base: f64, exponent: f64) -> f64 {
    #[cfg(all(target_arch = "wasm32", target_os = "unknown"))]
    {
        let k = (exponent * 11.).round();
        if (0. ..=11.).contains(&k) && k / 11. == exponent {
            let key = (base.to_bits(), k as u8);
            if let Some(&(_, _, result)) = TABLE.iter().find(|(b, s, _)| (*b, *s) == key) {
                return f64::from_bits(result);
            }
        }
    }
    base.powf(exponent)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[cfg(windows)]
    #[test]
    fn the_table_is_the_windows_pow() {
        for (base, k, result) in TABLE {
            let base = f64::from_bits(base);
            assert_eq!(
                base.powf(f64::from(k) / 11.).to_bits(),
                result,
                "{base}^({k}/11)"
            );
        }
    }

    #[test]
    fn every_base_and_step_is_in_the_table() {
        assert!(TABLE.iter().all(|(_, k, _)| *k <= 11));
        assert_eq!(step_pow(2., 0.5), 2_f64.powf(0.5));
    }
}
